function today(){let s="";try{s=new Intl.DateTimeFormat(lang==="es"?"es-US":"en-US",{weekday:"long",day:"numeric",month:"long",year:"numeric",timeZone:"America/New_York"}).format(new Date())}catch(e){}return s?s.charAt(0).toUpperCase()+s.slice(1)+" · "+(lang==="es"?"Nueva York":"New York"):""}

function cv(a,cls=""){const ph=FOTOS[a.id];if(ph)return `<div class="cv ft ${cls}"><img src="/assets/fotos/${a.id}-s.webp" srcset="/assets/fotos/${a.id}-s.webp 560w, /assets/fotos/${a.id}.webp 1200w" sizes="(max-width:700px) 100vw, 50vw" alt="" width="${ph.w}" height="${ph.h}" ${/wide|cine/.test(cls)?`fetchpriority="high" decoding="async"`:`loading="lazy" decoding="async"`} style="object-position:${ph.pos||"50% 30%"}"></div>`;const c=COV[a.id]||{f:"El Coro",bg:"#0b0b0b",fg:"#fff",c:a.tag,e:""};
 return `<div class="cv ${cls}" style="background:${c.bg};color:${c.fg};${c.bd?"box-shadow:inset 0 0 0 1px var(--rule);":""}${c.fs?`--fs:${c.fs};`:""}${c.al?`--al:${c.al};`:""}" aria-hidden="true"><div class="c"><b><i style="font-style:italic;font-size:.4em;letter-spacing:-.01em;margin-right:.07em">el</i>CORO</b><span>${a.tag}</span></div><div class="f">${c.f}</div><div class="c"><span>${c.e}</span><span>${c.c}</span></div></div>`}
const kl=a=>`<div class="kline"><a class="k" href="#${a.sec}">${t().sections[a.sec]}</a>${a.tag!==T.es.sections[a.sec]?`<span class="dot">·</span><a class="kt" href="#t-${slug(a.tag)}">${a.tag}</a>`:""}</div>`;
const by=a=>`<div class="by">${u().by} <b>${AUTORES[a.id]||u().newsroom}</b>${AUTORES[a.id]?"":` · ${lang==="es"?"Edición":"Edited by"}: <b>Yeyo Ruiz</b>`} · <time datetime="${a.date}">${fdate(a.date)}</time> · ${a.min} ${t().read}</div>`;
const card=(a,dek)=>`<a class="card" href="#${a.id}">${cv(a)}<div class="card-t"><span class="k">${t().sections[a.sec]}</span><h3 class="h h-m">${title(a)}</h3>${dek?`<p class="dek">${a.dek}</p>`:""}</div></a>`;
const mini=a=>`<a class="mini-row" href="#${a.id}"><div><span class="k">${a.tag}</span><h3 class="h h-s">${title(a)}</h3></div>${cv(a,"sq")}</a>`;
const SECKEYS=()=>Object.keys(t().sections).filter(k=>!["inicio","manifiesto"].includes(k));
function secLinks(cur){return SECKEYS().map(k=>`<a href="#${k}"${k===cur?' aria-current="page"':""}>${t().sections[k]}</a>`).join("")}
function trend(){const have=new Set(A.map(a=>a.tag));return `<b>${u().trending}</b>`+HOME.trend.filter(x=>have.has(x)).map(x=>`<a href="#t-${slug(x)}">${x}</a>`).join("")}
function acc(){
  return SECKEYS().map(k=>{const v=t().sections[k];const items=[[u().all(v),"#"+k],...(SUBS[k]||[]).map(x=>[x[0],x[1]]),...A.filter(a=>a.sec===k&&!(SUBS[k]||[]).some(s=>s[1]==="#"+a.id)).slice(0,3).map(a=>[title(a),"#"+a.id])];
    return `<div class="acc"><button type="button" aria-expanded="false" aria-controls="sub-${k}">${v}<i aria-hidden="true">+</i></button><div class="sub" id="sub-${k}" hidden>${items.map(([n,h])=>`<a href="${h}">${n}</a>`).join("")}</div></div>`}).join("");
}
function chart(list,max){return `<ol class="chart">${list.map(([n,v],i)=>`<li><span class="n">${i+1}</span><div><div class="a">${n}</div><div class="bar2"><i style="width:${v/max*100}%"></i></div></div><span class="v">${v}</span></li>`).join("")}</ol>`}
const TOPN=[["RAYE",11],["Rosalía",9],["Ella Langley",7],["Miranda Lambert",7],["Olivia Rodrigo",7],["Phoebe Bridgers",7],["Bruno Mars",6],["Leon Thomas",6],["Olivia Dean",6],["Taylor Swift",5]];
function mani(){return `<section class="blk mani"><div class="blkh"><h2 class="lbl">${t().manifestTitle}</h2><a href="#politica-editorial">${t().all} →</a></div><ul>${RULES[lang].map(([b,s],i)=>`<li><span class="n">${String(i+1).padStart(2,"0")}</span><b>${b}</b><span>${s}</span></li>`).join("")}</ul></section>`}

function home(){
  const a=byId(HOME.lead)||A[0];
  return `<div class="w"><section class="topg">
   <article class="lead"><a href="#${a.id}" tabindex="-1">${cv(a,"wide")}</a><div class="lead-t">${kl(a)}<a href="#${a.id}"><h1 class="h h-xl">${title(a)}</h1></a><p class="dek">${a.dek}</p>${by(a)}</div></article>
   <aside class="ess"><h2 class="lbl">${u().essential}</h2>${pick(HOME.ess).map(mini).join("")}</aside></section>
   <section class="row4">${pick(HOME.row).map(x=>card(x,false)).join("")}</section></div>
  <section class="minute"><div class="w"><div class="minute-h"><h2 class="h">${u().minute}</h2><span class="by">${u().minuteSub}</span></div><ol>${HOME.min.filter(m=>byId(m[0])).map(m=>`<li><a href="#${m[0]}"><span>${lang==="es"?m[1]:m[2]}</span></a></li>`).join("")}</ol></div></section>
  <div class="w"><section class="blk"><div class="blkh"><h2 class="lbl">${u().latest}</h2></div>${river(A.filter(x=>x.id!==a.id))}</section></div>
  <section class="band" style="margin-top:56px"><div class="w"><div class="band-h"><h2 class="disp">${u().listsH}</h2><div class="band-s"><span>${u().listsS}</span><a href="#lista-nominados">${t().all}</a></div></div>${chart(TOPN,11)}</div></section>
  <div class="w"><section class="blk"><div class="blkh"><h2 class="lbl">${u().duoH}</h2></div><div class="duo">${pick(HOME.duo).map(x=>card(x,true)).join("")}</div></section>
  ${mani()}</div>`;
}
const PAGE=8;
const sorted=ORD;
let riverList=[],riverShown=0;
function item(a){return `<a class="item" href="#${a.id}"><div><div class="kline"><span class="k">${t().sections[a.sec]}</span>${a.tag!==T.es.sections[a.sec]?`<span class="dot">·</span><span class="kt">${a.tag}</span>`:""}</div><h3 class="h">${title(a)}</h3><p class="dek">${a.dek}</p><div class="by">${fshort(a.date)} · ${a.min} ${t().read}</div></div>${cv(a,"sq")}</a>`}
function riverChunk(from,to){let h="",last=from?riverList[from-1].date:null;for(const a of riverList.slice(from,to)){if(a.date!==last){h+=`<div class="day">${dayLabel(a.date)}</div>`;last=a.date}h+=item(a)}return h}
const counter=()=>u().shown(riverShown,riverList.length);
function river(list){riverList=sorted(list);riverShown=Math.min(PAGE,riverList.length);
  return `<div class="river"><div><div id="feed">${riverChunk(0,riverShown)}</div>${riverList.length>PAGE?`<button class="more" id="more" type="button">${u().more}</button>`:""}<div class="count" id="count">${counter()}</div></div>${sidebar()}</div>`}
function sidebar(){const tags=[...new Set(A.map(a=>a.tag))];
  return `<aside class="side"><div class="box"><h4 class="lbl">${u().essentials}</h4><ol class="num">${pick(HOME.picks).map(a=>`<li><a href="#${a.id}">${title(a)}</a></li>`).join("")}</ol></div>
  <div class="box"><h4 class="lbl">${u().topics}</h4><div class="tags">${tags.map(x=>`<a href="#t-${slug(x)}">${x}</a>`).join("")}</div></div>
  <div class="promo"><span class="k">${u().promoK}</span><p class="h">${u().promoH}</p><p>${u().promoP}</p><a class="btn" href="#contacto">${u().promoA} →</a></div></aside>`}
function listPage(kick,name,desc,l){const f=l[0];const rest=l.slice(1);const others=A.filter(x=>!l.includes(x)).slice(0,4);
  return `<div class="w"><header class="sech"><span class="k">${kick}</span><h1 class="disp">${name}</h1>${desc?`<p class="secd">${desc}</p>`:""}</header>
  ${f?`<section class="feat-top"><a href="#${f.id}" tabindex="-1">${cv(f,"wide")}</a><div class="ft-t">${kl(f)}<a href="#${f.id}"><h2 class="h h-l">${title(f)}</h2></a><p class="dek">${f.dek}</p>${by(f)}</div></section>`:""}
  ${rest.length?`<section class="blk" style="padding-top:0">${river(rest)}</section>`:""}
  ${l.length<4?`<section class="blk"><div class="blkh"><h2 class="lbl">${u().moreIn}</h2></div><div class="row4" style="border-top:0;margin-top:0">${others.map(x=>card(x,false)).join("")}</div></section>`:""}</div>`}
function section(k){return listPage(u().section,t().sections[k],(SECD[lang]||{})[k],sorted(A.filter(a=>a.sec===k)))}
function enNota(a){const txt=(a.title+" "+a.body.replace(/<[^>]+>/g," ")),out=[];const prop=(COV[a.id]||{}).e||"";
 for(const k in BANCO){const b=BANCO[k];if([b.n].concat(b.a||[]).some(n=>txt.includes(n))&&b.n!==prop&&!(FOTOS[a.id]&&FOTOS[a.id].pie===b.n))out.push(k)}
 return out.sort((x,y)=>txt.indexOf(BANCO[x].n)-txt.indexOf(BANCO[y].n))}
function cuerpo(a){const ms=enNota(a),cr=lang==="es"?"Foto: cortesía de prensa":"Photo: press handout";
 const fig=k=>{const b=BANCO[k];return `<figure class="inph${b.w>b.h*1.15?" h":""}"><img src="/assets/banco/${k}.webp" srcset="/assets/banco/${k}-s.webp 560w, /assets/banco/${k}.webp 1200w" sizes="(max-width:700px) 100vw, 680px" alt="${b.n}" width="${b.w}" height="${b.h}" loading="lazy" decoding="async" style="object-position:${b.pos||"50% 25%"}"><figcaption><b>${b.n}</b><span>${cr}</span></figcaption></figure>`};
 const c=COV[a.id]||{};const dato=c.f&&!/<|\{/.test(c.f)?`<div class="dato"><b>${c.f}</b><span>${c.c||""}${c.e?"<br>"+c.e:""}</span></div>`:"";
 const partes=a.body.split(/(?=<h2)/);const ins=ms.slice(0,3).map(fig);
 if(!ins.length&&dato)ins.push(dato);else if(dato&&ins.length<partes.length-1)ins.splice(1,0,dato);
 let html="";partes.forEach((p,i)=>{if(i>0&&ins[i-1])html+=ins[i-1];html+=p});
 if(partes.length===1&&ins.length){const ps=html.split("</p>");html=ps.slice(0,2).join("</p>")+"</p>"+ins[0]+ps.slice(2).join("</p>")}
 const resto=ms.slice(3);if(ms.length>=4)html+=`<div class="enota"><span>${lang==="es"?"En esta nota":"In this story"}</span><div>${ms.map(k=>`<figure><img src="/assets/banco/${k}-s.webp" alt="${BANCO[k].n}" loading="lazy" decoding="async" style="object-position:${BANCO[k].pos||"50% 25%"}"><figcaption>${BANCO[k].n}</figcaption></figure>`).join("")}</div></div>`;
 return html}
function article(a){const url=location.href,enc=encodeURIComponent;
  const rel=A.filter(b=>b.id!==a.id&&b.sec===a.sec).concat(A.filter(b=>b.id!==a.id&&b.sec!==a.sec)).slice(0,4);
  return `<article class="art"><header class="w art-h">${kl(a)}<h1 class="h h-art">${title(a)}</h1><p class="dek dek-art">${a.dek}</p>
  <div class="byrow">${by(a)}<div class="share" aria-label="${u().share}"><button type="button" id="enBtn">${lang==="es"?"English":"Español"} ⇄</button><a href="https://wa.me/?text=${enc(title(a)+" "+url)}" target="_blank" rel="noopener">WhatsApp</a><a href="https://twitter.com/intent/tweet?text=${enc(title(a))}&amp;url=${enc(url)}" target="_blank" rel="noopener">X</a><a href="https://www.facebook.com/sharer/sharer.php?u=${enc(url)}" target="_blank" rel="noopener">Facebook</a><button type="button" id="copy">${u().copy}</button></div></div></header>
  ${FOTOS[a.id]?`<figure class="w art-cv art-foto"><img src="/assets/fotos/${a.id}.webp" srcset="/assets/fotos/${a.id}-s.webp 560w, /assets/fotos/${a.id}.webp 1200w" sizes="(max-width:960px) 100vw, 960px" alt="${lang==="es"?FOTOS[a.id].alt:(FOTOS[a.id].altEn||FOTOS[a.id].alt)}" width="${FOTOS[a.id].w}" height="${FOTOS[a.id].h}" fetchpriority="high" style="object-position:${FOTOS[a.id].pos||"50% 30%"}"><figcaption>${FOTOS[a.id].pie?FOTOS[a.id].pie+". ":""}${lang==="es"?FOTOS[a.id].credito:(FOTOS[a.id].creditoEn||FOTOS[a.id].credito)}</figcaption></figure>`:`<figure class="w art-cv">${cv(a,"cine")}<figcaption>${COV[a.id]&&COV[a.id].e?COV[a.id].e+" · ":""}${a.tag} · ${u().cover}</figcaption></figure>`}
  <div class="w body"><div class="prose">${cuerpo(a)}${(a.correcciones||[]).map(c=>`<p class="mono g">${c.tipo==="actualizacion"?(lang==="es"?"Actualización":"Update"):(lang==="es"?"Corrección":"Correction")} (${c.fecha}): ${c.nota}</p>`).join("")}<div class="en"><span class="k">${t().enNote}</span><p>${a.en}</p></div>
  <details class="src"><summary><span>${t().sources}</span><span class="n">${a.src.length}</span></summary><ol>${a.src.map(([n,s])=>`<li><a href="${s}" target="_blank" rel="noopener">${n}</a></li>`).join("")}</ol></details></div>
  <aside><div class="brief"><span class="k">${t().brief}</span><ul>${a.brief.map(b=>`<li>${b}</li>`).join("")}</ul></div></aside></div></article>
  <div class="w"><section class="blk"><div class="blkh"><h2 class="lbl">${u().keep}</h2></div><div class="row4" style="border-top:0;margin-top:0">${rel.map(x=>card(x,false)).join("")}</div></section></div>`;
}
function page(p){return `<article class="art"><header class="w art-h"><span class="k">${p.k[lang]}</span><h1 class="h h-art">${p.t[lang]}</h1></header><div class="w body"><div class="prose page">${p.body[lang]}</div><aside><nav class="brief pnav"><span class="k">El Coro</span><ul>${Object.entries(PAGES).map(([k,v])=>`<li><a href="#${k}"${CUR()===k?' aria-current="page"':""}>${v.t[lang]}</a></li>`).join("")}</ul></nav></aside></div></article>`}
function openOv(id,open){const o=$(id);o.hidden=!open;document.body.style.overflow=open?"hidden":"";if(id==="#ov")$("#menuBtn").setAttribute("aria-expanded",open);if(open&&id==="#sv")setTimeout(()=>$("#q").focus(),50)}
function chrome(){
  const x=(id,v)=>{const e=$(id);if(e)e.textContent=v};
  x("#today",today());x("#tagline",u().tagline);x("#subBtn",u().sub);x("#fslog",u().slogan);x("#fh1",u().sections);x("#fh4",u().follow);
  x("#langBtn",lang==="es"?"English":"Español");x("#mBtn",u().about);x("#themeBtn",u().theme);x("#homeBtn",u().home);x("#qLbl",u().search);
  x("#nlK",u().nlK);x("#nlH",u().nlH);x("#nlP",u().nlP);x("#nlL",u().nlL);x("#nlB",u().nlB);x("#nlS",u().nlS);
  $("#lgEs").setAttribute("aria-pressed",lang==="es");$("#lgEn").setAttribute("aria-pressed",lang==="en");$("#menuBtn").setAttribute("aria-label",u().menu);
}
function route(){
  const h=CUR();const a=A.find(x=>x.id===h);const s=a?a.sec:(T.es.sections[h]?h:"inicio");
  $("#secnav").innerHTML=secLinks(s);$("#acc").innerHTML=acc();$("#trend").innerHTML=trend();
  $("#fnav").innerHTML=secLinks();
  const pl=ks=>ks.map(k=>`<a href="#${k}">${PAGES[k].t[lang]}</a>`).join("");$("#fabout").innerHTML=pl(["quienes-somos","contacto","politica-editorial","anunciate"]);$("#flegal").innerHTML=pl(["privacidad","terminos"]);
  chrome();
  const tg=h.startsWith("t-")?[...new Set(A.map(x=>x.tag))].find(x=>"t-"+slug(x)===h):null;
  const pg=PAGES[h];
  $("#app").innerHTML=pg?page(pg):tg?listPage(u().topic,tg,"",sorted(A.filter(x=>x.tag===tg))):a?article(a):s==="inicio"?home():section(s);
  openOv("#ov",false);openOv("#sv",false);document.documentElement.lang=lang;fixLinks(document);if(window.__booted)scrollTo(0,0);window.__booted=1;
  if(window.__nt)document.title=a?`${title(a)} | El Coro Magazine`:pg?`${pg.t[lang]} | El Coro Magazine`:"El Coro Magazine";
  let ld=document.getElementById("ld");if(!ld){ld=document.createElement("script");ld.type="application/ld+json";ld.id="ld";document.body.appendChild(ld)}
  ld.textContent=JSON.stringify(a?{"@context":"https://schema.org","@type":"NewsArticle",headline:a.title,description:a.dek,datePublished:a.date+"T"+(a.hora||"09:00")+":00-05:00",dateModified:MOD(a),url:SITE+ROUTE[a.id],mainEntityOfPage:SITE+ROUTE[a.id],image:[SITE+(FOTOS[a.id]?"/assets/fotos/"+a.id+".jpg":(OG[a.id]||"/assets/og-default.jpg"))],inLanguage:"es",articleSection:T.es.sections[a.sec],author:AUTORES[a.id]?{"@type":"Person",name:AUTORES[a.id],url:"https://elcoromagazine.com/quienes-somos/"}:{"@type":"Organization",name:"Redacción El Coro",url:"https://elcoromagazine.com/quienes-somos/"},editor:{"@type":"Person",name:"Yeyo Ruiz",jobTitle:"Editor",url:"https://elcoromagazine.com/quienes-somos/"},isAccessibleForFree:true,keywords:[a.tag,T.es.sections[a.sec]].join(", "),publisher:{"@type":"NewsMediaOrganization",name:"El Coro Magazine",url:SITE,logo:{"@type":"ImageObject",url:SITE+"/assets/icon-512.png"}},citation:a.src.map(x=>x[1])}:{"@context":"https://schema.org","@type":"NewsMediaOrganization",name:"El Coro Magazine",url:"https://elcoromagazine.com",email:"press@elcoromagazine.com",slogan:"La música del mundo, en tiempo real.",sameAs:["https://www.instagram.com/elcoromagazine"],logo:{"@type":"ImageObject",url:"https://elcoromagazine.com/assets/icon-512.png",width:512,height:512},foundingDate:"2026",foundingLocation:{"@type":"Place",name:"Nueva York"},areaServed:["US","Latinoamérica","España"],knowsLanguage:["es","en"],publishingPrinciples:"https://elcoromagazine.com/politica-editorial/",correctionsPolicy:"https://elcoromagazine.com/politica-editorial/",ethicsPolicy:"https://elcoromagazine.com/politica-editorial/",masthead:"https://elcoromagazine.com/quienes-somos/",actionableFeedbackPolicy:"https://elcoromagazine.com/contacto/",employee:[{"@type":"Person",name:"Yeyo Ruiz",jobTitle:"Editor"}]});
}
function setLang(){window.__nt=1;lang=lang==="es"?"en":"es";try{localStorage.setItem("elcoro-lang",lang)}catch(e){}route()}
$("#menuBtn").onclick=()=>openOv("#ov",true);$("#closeBtn").onclick=()=>openOv("#ov",false);
$("#searchBtn").onclick=$("#searchBtn2").onclick=$("#searchBtn3").onclick=()=>{openOv("#ov",false);openOv("#sv",true)};$("#closeS").onclick=()=>openOv("#sv",false);
$("#langBtn").onclick=setLang;
$("#lgEs").onclick=()=>{if(lang!=="es")setLang()};$("#lgEn").onclick=()=>{if(lang!=="en")setLang()};
$("#subBtn").onclick=()=>{const n=$("#nl");if(n){n.scrollIntoView({behavior:"smooth"});setTimeout(()=>$("#nlMail").focus({preventScroll:true}),600)}};
$("#themeBtn").onclick=()=>{const r=document.documentElement,c=r.dataset.theme==="dark"?"light":"dark";r.dataset.theme=c;try{localStorage.setItem("elcoro-theme",c)}catch(e){}};
document.addEventListener("click",e=>{
  const b=e.target.closest(".acc>button");if(b){const o=b.getAttribute("aria-expanded")==="true";b.setAttribute("aria-expanded",!o);b.querySelector("i").textContent=o?"+":"−";b.nextElementSibling.hidden=o}
  if(e.target.closest("#enBtn"))setLang();
  if(e.target.closest("#more")){const n=Math.min(riverShown+PAGE,riverList.length);$("#feed").insertAdjacentHTML("beforeend",riverChunk(riverShown,n));fixLinks($("#feed"));riverShown=n;$("#count").textContent=counter();if(riverShown>=riverList.length)$("#more").disabled=true}
  const c=e.target.closest("#copy");if(c){const done=()=>c.textContent=u().copied;if(navigator.clipboard)navigator.clipboard.writeText(location.href).then(done,()=>c.textContent=location.href);else c.textContent=location.href}
  const l=e.target.closest(".ov a");if(l&&l.getAttribute("href")===location.hash){openOv("#ov",false);openOv("#sv",false)}
});
$("#nlForm").addEventListener("submit",e=>{e.preventDefault();const f=e.target,msg=$("#nlS");
  const live=location.hostname.endsWith("elcoromagazine.com");
  if(!live){msg.textContent=u().nlPrev;return}
  fetch("/suscribir.php",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams(new FormData(f)).toString()}).then(r=>r.json()).then(j=>{if(!j.ok)throw 0;f.reset();msg.textContent=u().nlOk}).catch(()=>{msg.textContent=u().nlErr})});
$("#q").addEventListener("input",e=>{const q=e.target.value.trim().toLowerCase();const norm=s=>s.normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase();
  const r=q?A.filter(a=>norm(a.title+" "+a.titleEn+" "+a.dek+" "+a.tag).includes(norm(q))):[];
  $("#res").innerHTML=r.map(a=>`<li><a href="#${a.id}"><span class="k">${a.tag}</span><b>${title(a)}</b></a></li>`).join("")+(q&&!r.length?`<p class="none">${u().none}</p>`:"")});
addEventListener("keydown",e=>{if(e.key==="Escape"){openOv("#ov",false);openOv("#sv",false)}});

addEventListener("scroll",()=>{const art=!!document.querySelector(".art .prose");const d=document.documentElement;$("#rp").style.width=art?(100*d.scrollTop/Math.max(1,d.scrollHeight-d.clientHeight))+"%":"0";document.body.classList.toggle("sc",scrollY>(($("#hdr")||{}).offsetHeight||160))},{passive:true});
route();
